async function doSave() {
  if (!validate()) { name.focus(); return; }
  form.dataset.state = 'saving';
  save.disabled = true;
  saveError.hidden = true;
  try {
    await persist(name.value.trim());
    saved = name.value;
    status.textContent = 'Saved.';
  } catch {
    saveError.hidden = false;
    save.disabled = false;
  } finally {
    form.dataset.state = 'idle';
